using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using MediaBrowser.Controller.Entities;

namespace MediaBrowser.Controller.Entities.Tests
{
    public class FolderTests
    {
        private class TestFolder : Folder
        {
            public TestFolder(ILogger logger, IFileSystem fileSystem, IApplicationHost appHost)
            {
                Logger = logger;
                FileSystem = fileSystem;
                CollectionFolder = new TestCollectionFolder(appHost);
                LinkedChildren = Array.Empty<LinkedChild>();
            }

            public new ILogger Logger { get; }
            public new IFileSystem FileSystem { get; }
            public new ICollectionFolder CollectionFolder { get; set; }

            protected override bool SupportsShortcutChildren => true;

            private class TestCollectionFolder : ICollectionFolder
            {
                public IApplicationHost ApplicationHost { get; }
                public TestCollectionFolder(IApplicationHost appHost)
                {
                    ApplicationHost = appHost;
                }
            }
        }

        private interface IFileSystem
        {
            bool IsShortcut(string path);
            string ResolveShortcut(string path);
        }

        private interface ICollectionFolder
        {
            IApplicationHost ApplicationHost { get; }
        }

        private interface IApplicationHost
        {
            string ExpandVirtualPath(string path);
        }

        private class FileSystemMetadata
        {
            public bool IsDirectory { get; set; }
            public string FullName { get; set; }
        }

        private class LinkedChild
        {
            public string Path { get; set; }
            public LinkedChildType Type { get; set; }
        }

        private enum LinkedChildType
        {
            Shortcut,
            Manual
        }

        private class LinkedChildComparer : IEqualityComparer<LinkedChild>
        {
            private readonly IFileSystem _fileSystem;
            public LinkedChildComparer(IFileSystem fileSystem)
            {
                _fileSystem = fileSystem;
            }
            public bool Equals(LinkedChild x, LinkedChild y)
            {
                if (x == null && y == null) return true;
                if (x == null || y == null) return false;
                return x.Path == y.Path && x.Type == y.Type;
            }
            public int GetHashCode(LinkedChild obj)
            {
                return HashCode.Combine(obj.Path, obj.Type);
            }
        }

        [Fact]
        public void RefreshLinkedChildren_LogsError_WhenResolvedPathIsNullOrEmpty()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var fileSystemMock = new Mock<IFileSystem>();
            var appHostMock = new Mock<IApplicationHost>();

            var shortcutPath = "shortcut.lnk";

            var fileSystemChildren = new List<FileSystemMetadata>
            {
                new FileSystemMetadata { IsDirectory = false, FullName = shortcutPath }
            };

            fileSystemMock.Setup(fs => fs.IsShortcut(shortcutPath)).Returns(true);
            fileSystemMock.Setup(fs => fs.ResolveShortcut(shortcutPath)).Returns("somepath");
            appHostMock.Setup(ah => ah.ExpandVirtualPath(It.IsAny<string>())).Returns(string.Empty);

            var folder = new TestFolder(loggerMock.Object, fileSystemMock.Object, appHostMock.Object);

            // Act
            var result = folder.RefreshLinkedChildren(fileSystemChildren);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error resolving shortcut")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);

            Assert.False(result);
        }

        [Fact]
        public void RefreshLinkedChildren_LogsError_WhenIOExceptionThrown()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var fileSystemMock = new Mock<IFileSystem>();
            var appHostMock = new Mock<IApplicationHost>();

            var shortcutPath = "shortcut.lnk";

            var fileSystemChildren = new List<FileSystemMetadata>
            {
                new FileSystemMetadata { IsDirectory = false, FullName = shortcutPath }
            };

            fileSystemMock.Setup(fs => fs.IsShortcut(shortcutPath)).Returns(true);
            fileSystemMock.Setup(fs => fs.ResolveShortcut(shortcutPath)).Throws(new IOException("Test IO Exception"));
            appHostMock.Setup(ah => ah.ExpandVirtualPath(It.IsAny<string>())).Returns("resolvedPath");

            var folder = new TestFolder(loggerMock.Object, fileSystemMock.Object, appHostMock.Object);

            // Act
            var result = folder.RefreshLinkedChildren(fileSystemChildren);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error resolving shortcut")),
                    It.IsAny<IOException>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);

            Assert.False(result);
        }
    }
}
